public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null) {
        return result;
    }
    int n = nums.length;
    if (n == 0) {
        result.add(new ArrayList<>());
        return result;
    }
    boolean[] used = new boolean[n];
    List<Integer> current = new ArrayList<>(n);
    backtrack(nums, used, current, result);
    return result;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> result) {
    if (current.size() == nums.length) {
        result.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true;
        current.add(nums[i]);
        backtrack(nums, used, current, result);
        current.remove(current.size() - 1);
        used[i] = false;
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null) {
        throw new IllegalArgumentException("Input list cannot be null");
    }
    if (strings.isEmpty()) {
        return 0;
    }
    // Ensure no null strings
    for (String s : strings) {
        if (s == null) {
            throw new IllegalArgumentException("Strings in the list cannot be null");
        }
    }
    // Find the shortest string to minimize substring enumeration
    String shortest = strings.get(0);
    for (String s : strings) {
        if (s.length() < shortest.length()) {
            shortest = s;
        }
    }
    int shortestLen = shortest.length();
    // Iterate over possible lengths from longest to shortest
    for (int len = shortestLen; len >= 1; len--) {
        // For each starting index in the shortest string
        for (int start = 0; start <= shortestLen - len; start++) {
            String candidate = shortest.substring(start, start + len);
            String reversed = new StringBuilder(candidate).reverse().toString();
            boolean allMatch = true;
            for (String s : strings) {
                if (!(s.contains(candidate) || s.contains(reversed))) {
                    allMatch = false;
                    break;
                }
            }
            if (allMatch) {
                return len;
            }
        }
    }
    return 0;
}

