public boolean canArrange(int[] arr, int k) {
    if (arr == null) {
        throw new IllegalArgumentException("Input array cannot be null.");
    }
    if (k <= 0) {
        throw new IllegalArgumentException("Divisor k must be a positive integer.");
    }
    if (arr.length % 2 != 0) {
        return false; // cannot pair all elements if array length is odd
    }

    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k; // handle negative numbers
        freq[r]++;
    }

    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }

    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) { // when k is even and r == k/2
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    java.util.ArrayList<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        graph[u].add(v);
        graph[v].add(u);
    }
    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -2);
    parent[0] = -1;
    java.util.ArrayList<Integer> order = new java.util.ArrayList<>();
    int[] stack = new int[n];
    int top = 0;
    stack[top++] = 0;
    while (top > 0) {
        int node = stack[--top];
        order.add(node);
        for (int nei : graph[node]) {
            if (parent[nei] == -2) {
                parent[nei] = node;
                stack[top++] = nei;
            }
        }
    }
    boolean[] hasAppleInSubtree = new boolean[n];
    System.arraycopy(hasApple, 0, hasAppleInSubtree, 0, n);
    int total = 0;
    for (int i = order.size() - 1; i >= 0; i--) {
        int node = order.get(i);
        for (int nei : graph[node]) {
            if (parent[nei] == node) {
                if (hasAppleInSubtree[nei]) {
                    total += 2;
                    hasAppleInSubtree[node] = true;
                }
            }
        }
    }
    return total;
}

public String sortString(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (s.isEmpty()) {
        return "";
    }
    java.util.TreeMap<Character, Integer> map = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        map.merge(c, 1, Integer::sum);
    }
    StringBuilder result = new StringBuilder(s.length());
    while (!map.isEmpty()) {
        // Step 1: pick smallest
        char last = map.firstKey();
        result.append(last);
        decrementOrRemove(map, last);
        // Step 2: pick increasing sequence
        while (true) {
            Character next = map.higherKey(last);
            if (next == null) break;
            last = next;
            result.append(last);
            decrementOrRemove(map, last);
        }
        if (map.isEmpty()) break;
        // Step 4: pick largest
        last = map.lastKey();
        result.append(last);
        decrementOrRemove(map, last);
        // Step 5: pick decreasing sequence
        while (true) {
            Character next = map.lowerKey(last);
            if (next == null) break;
            last = next;
            result.append(last);
            decrementOrRemove(map, last);
        }
    }
    return result.toString();
}

private void decrementOrRemove(java.util.TreeMap<Character, Integer> map, char key) {
    int count = map.get(key);
    if (count == 1) {
        map.remove(key);
    } else {
        map.put(key, count - 1);
    }
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // dp[k] holds all possible sums of subsets of size k
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] dp = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new HashSet<>();
    }
    dp[0].add(0);
    for (int num : nums) {
        // iterate k in reverse to avoid using updated values in the same iteration
        for (int k = Math.min(n / 2, n); k >= 1; k--) {
            for (int prevSum : dp[k - 1]) {
                dp[k].add(prevSum + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        long product = (long) totalSum * k;
        if (product % n != 0) {
            continue;
        }
        int target = (int) (product / n);
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    // dp[i] represents the minimum cost to reach step i
    // We only need the last two values
    int prev2 = 0; // dp[0]
    int prev1 = 0; // dp[1]
    for (int i = 2; i <= n; i++) {
        int costFromPrev1 = prev1 + cost[i - 1];
        int costFromPrev2 = prev2 + cost[i - 2];
        int current = Math.min(costFromPrev1, costFromPrev2);
        prev2 = prev1;
        prev1 = current;
    }
    return prev1;
}

