public boolean hasAllCodes(String s, int k) {
    if (s == null) {
        throw new IllegalArgumentException("Input string s cannot be null");
    }
    if (k <= 0) {
        throw new IllegalArgumentException("k must be positive");
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    int maxMask = 1 << k;
    boolean[] seen = new boolean[maxMask];
    int count = 0;
    int mask = 0;
    int maskLimit = maxMask - 1;
    for (int i = 0; i < n; i++) {
        mask = ((mask << 1) & maskLimit) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[mask]) {
                seen[mask] = true;
                count++;
                if (count == maxMask) {
                    return true;
                }
            }
        }
    }
    return false;
}

