        int count = (int) state[2];
        if (idx == n) {
            if (count > max) max = count;
            continue;
        }
        for (int end = idx + 1; end <= n; end++) {
            String sub = s.substring(idx, end);
            if (!used.contains(sub)) {
                java.util.Set<String> newUsed = new java.util.HashSet<>(used);
                newUsed.add(sub);
                stack.push(new Object[]{end, newUsed, count + 1});
            }
        }
    }
    return max;
}

public int minOperations(String[] logs) {
    if (logs == null || logs.length == 0) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        if (log.equals("../")) {
            if (depth > 0) {
                depth--;
            }
        } else if (log.equals("./")) {
            // stay in the same folder, do nothing
        } else {
            // any other log is considered a folder entry
            depth++;
        }
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    long maxSum = 26L * n;
    if (k < n || k > maxSum) {
        throw new IllegalArgumentException("k out of valid range");
    }
    int delta = k - n; // additional value needed beyond all 'a's
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    for (int i = n - 1; i >= 0 && delta > 0; i--) {
        int add = Math.min(25, delta);
        result[i] = (char) ('a' + add);
        delta -= add;
    }
    return new String(result);
}

