public static int longestLine(int[][] mat) {
    if (mat == null) {
        throw new IllegalArgumentException("Input matrix cannot be null");
    }
    int m = mat.length;
    if (m == 0) {
        return 0;
    }
    int n = mat[0].length;
    if (n == 0) {
        return 0;
    }
    // Validate rows
    for (int i = 0; i < m; i++) {
        if (mat[i] == null) {
            throw new IllegalArgumentException("Row " + i + " is null");
        }
        if (mat[i].length != n) {
            throw new IllegalArgumentException("Row " + i + " length differs from first row");
        }
    }

    int[][] dpH = new int[m][n]; // horizontal
    int[][] dpV = new int[m][n]; // vertical
    int[][] dpD = new int[m][n]; // diagonal
    int[][] dpA = new int[m][n]; // anti-diagonal
    int max = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dpH[i][j] = (j > 0 ? dpH[i][j - 1] : 0) + 1;
                dpV[i][j] = (i > 0 ? dpV[i - 1][j] : 0) + 1;
                dpD[i][j] = (i > 0 && j > 0 ? dpD[i - 1][j - 1] : 0) + 1;
                dpA[i][j] = (i > 0 && j < n - 1 ? dpA[i - 1][j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(dpH[i][j], dpV[i][j]),
                                         Math.max(dpD[i][j], dpA[i][j]));
                if (localMax > max) {
                    max = localMax;
                }
            } else {
                dpH[i][j] = dpV[i][j] = dpD[i][j] = dpA[i][j] = 0;
            }
        }
    }
    return max;
}

public static String addThousandSeparator(int n) {
    // Handle zero explicitly
    if (n == 0) {
        return "0";
    }

    // Convert to string and handle negative sign separately
    String numStr = Integer.toString(n);
    boolean isNegative = false;
    if (numStr.charAt(0) == '-') {
        isNegative = true;
        numStr = numStr.substring(1);
    }

    StringBuilder sb = new StringBuilder();
    int count = 0;
    for (int i = numStr.length() - 1; i >= 0; i--) {
        sb.append(numStr.charAt(i));
        count++;
        if (count == 3 && i != 0) {
            sb.append('.');
            count = 0;
        }
    }

    // Reverse to get the correct order
    sb.reverse();

    // Prepend negative sign if needed
    if (isNegative) {
        sb.insert(0, '-');
    }

    return sb.toString();
}

public static int squarePermutations(int[] A) {
    if (A == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = A.length;
    if (n == 0) {
        return 0;
    }
    // Sort to handle duplicates
    int[] arr = A.clone();
    java.util.Arrays.sort(arr);
    // Precompute adjacency matrix
    boolean[][] adj = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = arr[i] + arr[j];
            int r = (int) Math.sqrt(sum);
            adj[i][j] = (r * r == sum);
        }
    }
    int fullMask = (1 << n) - 1;
    long[][] memo = new long[1 << n][n];
    for (int i = 0; i < (1 << n); i++) {
        java.util.Arrays.fill(memo[i], -1L);
    }
    java.util.function.BiFunction<Integer, Integer, Long> dfs = new java.util.function.BiFunction<>() {
        @Override
        public Long apply(Integer mask, Integer last) {
            if (mask == fullMask) {
                return 1L;
            }
            long cached = memo[mask][last];
            if (cached != -1L) {
                return cached;
            }
            long count = 0L;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue;
                if (!adj[last][next]) continue;
                // Skip duplicates: if next has same value as previous and previous not used
                if (next > 0 && arr[next] == arr[next - 1] && (mask & (1 << (next - 1))) == 0) {
                    continue;
                }
                count += apply(mask | (1 << next), next);
            }
            memo[mask][last] = count;
            return count;
        }
    };
    long result = 0L;
    for (int start = 0; start < n; start++) {
        // Skip duplicate starting positions
        if (start > 0 && arr[start] == arr[start - 1]) {
            continue;
        }
        result += dfs.apply(1 << start, start);
    }
    return (int) result;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    for (int h : heights) {
        if (h < 0) {
            throw new IllegalArgumentException("Bar heights must be non-negative");
        }
    }
    try {
        int n = heights.length;
        java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
        stack.push(-1); // sentinel
        long maxArea = 0;
        for (int i = 0; i < n; i++) {
            while (stack.peek() != -1 && heights[i] < heights[stack.peek()]) {
                int height = heights[stack.pop()];
                int width = i - stack.peek() - 1;
                long area = (long) height * width;
                if (area > maxArea) {
                    maxArea = area;
                }
            }
            stack.push(i);
        }
        while (stack.peek() != -1) {
            int height = heights[stack.pop()];
            int width = n - stack.peek() - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        return (int) maxArea;
    } catch (Exception e) {
        throw new RuntimeException("Error computing largest rectangle area", e);
    }
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        int start = Math.max(0, sum - n + 1);
        int end = Math.min(m - 1, sum);
        if (sum % 2 == 0) {
            for (int i = end; i >= start; i--) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        } else {
            for (int i = start; i <= end; i++) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Step 1: Find the largest index i such that digits[i] < digits[i + 1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        // No higher permutation exists
        return -1;
    }

    // Step 2: Find the largest index j > i such that digits[j] > digits[i]
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Step 3: Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Step 4: Reverse the subarray from i+1 to end
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert back to integer, handling potential overflow
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        // Result exceeds integer range
        return -1;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
