private static List<String> build(int n, int m) {
    List<String> res = new ArrayList<>();
    if (n == 0) {
        res.add("");
        return res;
    }
    if (n == 1) {
        res.add("0");
        res.add("1");
        res.add("8");
        return res;
    }
    List<String> inner = build(n - 2, m);
    for (String s : inner) {
        if (n != m) {
            res.add("0" + s + "0");
        }
        res.add("1" + s + "1");
        res.add("6" + s + "9");
        res.add("8" + s + "8");
        res.add("9" + s + "6");
    }
    return res;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        throw new IllegalArgumentException("points must contain exactly three points");
    }
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            throw new IllegalArgumentException("each point must be an array of two integers");
        }
    }
    long x1 = points[0][0], y1 = points[0][1];
    long x2 = points[1][0], y2 = points[1][1];
    long x3 = points[2][0], y3 = points[2][1];
    long area2 = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);
    return area2 != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    int maxLen = 0;
    int currentLen = 0;
    char prevChar = '\0';
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (i == 0 || c != prevChar) {
            currentLen = 1;
        } else {
            currentLen++;
        }
        if (currentLen > maxLen) {
            maxLen = currentLen;
        }
        prevChar = c;
    }
    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    if (current > n) {
        return;
    }
    result.add(current);
    for (int d = 0; d <= 9; d++) {
        long next = (long) current * 10 + d;
        if (next > n) {
            break;
        }
        dfs((int) next, n, result);
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    long sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    if (sum > Integer.MAX_VALUE || sum < Integer.MIN_VALUE) {
        throw new ArithmeticException("Sum exceeds integer range");
    }
    return (int) sum;
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < min) {
                min = candidate;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (s.isEmpty()) {
        return s;
    }
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        result.append(new StringBuilder(words[i]).reverse());
        if (i < words.length - 1) {
            result.append(' ');
        }
    }
    return result.toString();
}
